def top_3_frequent(nums):
    if len(nums) == 0:
        return []

    frequency_dict = {}
    for num in nums:
        if num in frequency_dict:
            frequency_dict[num] += 1
        else:
            frequency_dict[num] = 1

    sorted_items = sorted(frequency_dict.items(), key=lambda x: x[1], reverse=True)

    result = []
    for i in range(min(3, len(sorted_items))):
        result.append((sorted_items[i][0], sorted_items[i][1]))

    # Note: this function returns the top 3 items
    # If there are ties in frequency the order may vary
    return result
